// Sends report emails to shop owners.
import { saveReport } from './store.js';
import { sendMail } from './mail.js';
import { renderCorrection, renderDaily, renderWeekly } from './report_render.js';

async function sendReport(shop, kind, id, html, subject) {
  await saveReport(`${kind}-${shop.id}-${id}`, html);
  await sendMail(shop.email, subject, html);
  return { shopId: shop.id, kind, bytes: html.length };
}

export function sendDailyReport(shop, rows, day) {
  return sendReport(shop, 'daily', day, renderDaily(shop, rows, day), `Your report for ${day}`);
}

export function sendWeeklyReport(shop, rows, weekStart) {
  return sendReport(shop, 'weekly', weekStart, renderWeekly(shop, rows, weekStart), `Your report for the week of ${weekStart}`);
}

export function sendCorrection(shop, rows, day, note) {
  return sendReport(shop, 'correction', day, renderCorrection(shop, rows, day, note), `Corrected report for ${day}`);
}
